using KarakusAluminyum.Web.Services;using KarakusAluminyum.Web.Data;using KarakusAluminyum.Web.Models;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;
namespace KarakusAluminyum.Web.Areas.Admin.Controllers;
[Area("Admin"),Authorize(Roles="Admin,Editor"),Route("yonetim/projeler")]
public class ProjectsController:Controller{private readonly AppDbContext _db; private readonly IWebHostEnvironment _env; public ProjectsController(AppDbContext db, IWebHostEnvironment env){_db=db;_env=env;}
[HttpGet("")]public async Task<IActionResult> Index()=>View(await _db.Projects.OrderByDescending(x=>x.CreatedUtc).ToListAsync());
[HttpGet("ekle")]public IActionResult Create()=>View("Edit",new PortfolioProject());
[HttpPost("ekle"),ValidateAntiForgeryToken]public async Task<IActionResult>Create(PortfolioProject m, IFormFile? imageFile){if(!ModelState.IsValid)return View("Edit",m);try{m.Image=await AdminImageUpload.SaveAsync(imageFile,_env) ?? m.Image;}catch(InvalidOperationException ex){ModelState.AddModelError("Image",ex.Message);return View("Edit",m);}m.Slug=Slug(m.Slug);m.CreatedUtc=m.UpdatedUtc=DateTime.UtcNow;_db.Projects.Add(m);await _db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
[HttpGet("duzenle/{id:int}")]public async Task<IActionResult>Edit(int id){var m=await _db.Projects.FindAsync(id);return m is null?NotFound():View(m);}
[HttpPost("duzenle/{id:int}"),ValidateAntiForgeryToken]public async Task<IActionResult>Edit(int id,PortfolioProject m, IFormFile? imageFile){if(id!=m.Id)return BadRequest();if(!ModelState.IsValid)return View(m);var x=await _db.Projects.FindAsync(id);if(x is null)return NotFound();try{var uploaded=await AdminImageUpload.SaveAsync(imageFile,_env);if(uploaded is not null)m.Image=uploaded;}catch(InvalidOperationException ex){ModelState.AddModelError("Image",ex.Message);return View(m);}x.Title=m.Title;x.Slug=Slug(m.Slug);x.Type=m.Type;x.Summary=m.Summary;x.Image=m.Image;x.Location=m.Location;x.Content=m.Content;x.IsPublished=m.IsPublished;x.UpdatedUtc=DateTime.UtcNow;await _db.SaveChangesAsync();return RedirectToAction(nameof(Index));}
[HttpPost("sil/{id:int}"),ValidateAntiForgeryToken]public async Task<IActionResult>Delete(int id){var x=await _db.Projects.FindAsync(id);if(x is not null){_db.Remove(x);await _db.SaveChangesAsync();}return RedirectToAction(nameof(Index));}
private static string Slug(string s)=>string.Join('-',s.Trim().ToLowerInvariant().Replace('ı','i').Replace('ğ','g').Replace('ü','u').Replace('ş','s').Replace('ö','o').Replace('ç','c').Split(' ',StringSplitOptions.RemoveEmptyEntries));}
